package net.officefloor.hq.app.claim;

import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.flag.FlagRepository;
import net.officefloor.hq.app.period.PeriodCap;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.Rollups;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Open each selected claim that can be opened, in list order (people in list order, newest
 *  claim first within a person), giving each the sheet's next number. Each is opened as a single open would be,
 *  with its OPEN line in its status log, its CLAIM_OPENED line and then how the sheet's figures moved over it. A selected claim that cannot be
 *  opened (the sheet is archived, the user's role may not open, not on the sheet, not a DRAFT, dated in a closed period, its person already at its period's cap of OPEN or PENDING claims, or with an empty note and a due above the note threshold in force on its date, or its person flagged in force and the user not a steward) is left as it is and counted as refused. One whose due is above the review threshold in force on
 *  its date goes to REVIEW instead, unnumbered, with a CLAIM_REVIEW line, and is counted as opened. */
public class BulkOpenClaims {
    public void open(@PathVariable("sheetId") String sheetId, @Val BulkOpenInput input, ClaimRepository claims, ClaimLogRepository log,
            PersonRepository people, PeriodRepository periods, RateRepository rates, RoleRepository roles, SettingRepository settings, SheetRepository sheets,
            FlagRepository flags, Rollups rollups, Audit audit, Out<BulkOpenResponse> result) {
        String sheet = sheetId.trim();
        periods.lockSheet(sheet);
        int opened = 0;
        if (sheets.archived(sheet)) {
            result.set(new BulkOpenResponse(0, input.claimIds().size()));
            return;
        }
        if (!settings.permissions(sheet).allows("open", roles.of(sheet, input.user()))) {
            result.set(new BulkOpenResponse(0, input.claimIds().size()));
            return;
        }
        for (Person person : people.list(sheet)) {
            List<Claim> theirs = claims.listForPerson(sheet, person.id()).stream()
                    .filter(c -> input.claimIds().contains(c.id())).toList();
            for (Claim claim : theirs) {
                if (claim.status().canBecome(ClaimStatus.OPEN) && periods.closedOn(sheet, claim.dueBy()) == null
                        && PeriodCap.reached(claim, periods, claims) == null
                        && ClaimStatusChange.noteRequired(claim, claims, people, rates, settings, sheets) == null
                        && !flagged(claim, input.user(), roles, flags)) {
                    Rollup before = rollups.take(sheet);
                    boolean review = ClaimStatusChange.reviewRequired(claim, claims, people, rates, settings, sheets);
                    String number = review ? null : claims.nextNumber(sheet, claim.dueBy());
                    claims.changeStatus(claim, review ? ClaimStatus.REVIEW : ClaimStatus.OPEN, number,
                            claim.settledDue(), input.user());
                    log.record(claim, input.user());
                    audit.record((review ? "CLAIM_REVIEW" : "CLAIM_OPENED") + " sheet=" + sheet + " by=" + input.user()
                            + " person=" + person.name() + " amount=" + claim.amount().toPlainString()
                            + " date=" + claim.date() + (review ? "" : " number=" + number));
                    rollups.record(sheet, input.user(), before);
                    opened++;
                }
            }
        }
        result.set(new BulkOpenResponse(opened, input.claimIds().size() - opened));
    }

    private static boolean flagged(Claim claim, String user, RoleRepository roles, FlagRepository flags) {
        try {
            RefuseFlaggedOpen.refuse(claim, user, roles, flags);
            return false;
        } catch (ClaimStatusNotAllowedException e) {
            return true;
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the body and refuse it before anything is read: a signed-in user, a known action, and a reason for a
 *  reject (a resettle freezes a SETTLED claim again; a delete makes a DRAFT DELETED, a restore a DELETED one a DRAFT again). A void's reason, chosen from the sheet's list, is kept
 *  (blank: none) and checked once the claim is loaded. */
public class ValidateClaimStatus {
    public void validate(@RequestBody ClaimStatusRequest request, Out<ClaimStatusInput> body)
            throws InvalidClaimException {
        if (request == null || request.user() == null || request.user().isBlank()) {
            throw new InvalidClaimException("Sign in before changing claims.");
        }
        String action = request.action() == null ? "" : request.action().trim();
        ClaimStatus to = switch (action) {
            case "open", "reject", "review" -> ClaimStatus.OPEN;
            case "settle", "approve", "resettle" -> ClaimStatus.SETTLED;
            case "void" -> ClaimStatus.VOID;
            case "delete" -> ClaimStatus.DELETED;
            case "restore" -> ClaimStatus.DRAFT;
            default -> throw new InvalidClaimException("Unknown claim action: " + action + ".");
        };
        String reason = null;
        if (action.equals("reject")) {
            reason = request.reason() == null ? "" : request.reason().trim();
            if (reason.isEmpty()) {
                throw new InvalidClaimException("Give a reason to reject a claim.");
            }
        } else if (action.equals("void") && request.reason() != null && !request.reason().isBlank()) {
            reason = request.reason().trim();
        }
        body.set(new ClaimStatusInput(request.user().trim(), action, to, reason));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

/** Fails when the claim is not on the sheet. */
public class LoadClaim {
    public void load(@PathVariable("sheetId") String sheetId, @PathVariable("claimId") String claimId,
            ClaimRepository repository, Out<Claim> claim) throws ClaimNotFoundException {
        Claim found = null;
        try {
            found = repository.find(sheetId.trim(), Long.parseLong(claimId.trim()));
        } catch (NumberFormatException e) {
            // not an id: not found
        }
        if (found == null) {
            throw new ClaimNotFoundException(claimId);
        }
        claim.set(found);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.flag.FlagRepository;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.plugin.variable.Val;

/** Refuse opening a claim of a person flagged in force on the sheet's today (today on or before the flag's until
 *  date) unless the user acts as a steward. Shared by a single open, the bulk open and a paste. */
public class RefuseFlaggedOpen {
    public void refuse(@Val ClaimStatusInput input, @Val Claim loaded, RoleRepository roles, FlagRepository flags)
            throws ClaimStatusNotAllowedException {
        if (input.action().equals("open")) {
            refuse(loaded, input.user(), roles, flags);
        }
    }

    /** Throws when the user may not open the claim because its person is flagged. */
    static void refuse(Claim claim, String user, RoleRepository roles, FlagRepository flags)
            throws ClaimStatusNotAllowedException {
        String reason = flags.inForce(claim.sheetId(), claim.personId());
        if (reason != null && !Role.STEWARD.equals(roles.of(claim.sheetId(), user))) {
            throw new ClaimStatusNotAllowedException("This person is flagged (" + reason
                    + "); only a steward can open their claims.");
        }
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.claim.Claim;
import net.officefloor.plugin.variable.Val;

/** Refuse opening, settling, voiding, moving, deferring, splitting or adding a proof to a claim whose due-by falls inside a closed period. */
public class RefuseClosedClaim {
    public void refuse(@Val Claim loaded, PeriodRepository periods) throws ClosedPeriodException {
        periods.lockSheet(loaded.sheetId());
        Period closed = periods.closedOn(loaded.sheetId(), loaded.dueBy());
        if (closed != null) {
            throw new ClosedPeriodException(closed);
        }
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimStatusInput;
import net.officefloor.plugin.variable.Val;

/** Refuse opening a claim whose person already has as many OPEN or PENDING claims in its period as the period's cap. */
public class RefuseCappedOpen {
    public void refuse(@Val ClaimStatusInput input, @Val Claim loaded, PeriodRepository periods, ClaimRepository claims)
            throws CappedPeriodException {
        if (!input.action().equals("open") && !input.action().equals("review")) {
            return;
        }
        Period capped = PeriodCap.reached(loaded, periods, claims);
        if (capped != null) {
            throw new CappedPeriodException(capped);
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.voidreason.VoidReasonRepository;
import net.officefloor.plugin.variable.Val;

/** While the sheet's list of void reasons is not empty, refuse a void that does not give a reason on it. */
public class RefuseVoidWithoutReason {
    public void refuse(@Val ClaimStatusInput input, @Val Claim loaded, VoidReasonRepository reasons)
            throws ClaimStatusNotAllowedException {
        if (!input.action().equals("void") || !reasons.any(loaded.sheetId())) {
            return;
        }
        if (input.reason() == null) {
            throw new ClaimStatusNotAllowedException("Choose a void reason to void this claim.");
        }
        if (!reasons.exists(loaded.sheetId(), input.reason())) {
            throw new ClaimStatusNotAllowedException(input.reason() + " is not a void reason on this sheet.");
        }
    }
}
package net.officefloor.hq.app.rollup;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

/** Take the sheet's figures before the change, so the change's audit can record how they moved. */
public class TakeRollup {
    public void take(@PathVariable("sheetId") String sheetId, Rollups rollups, Out<Rollup> before) {
        before.set(rollups.take(sheetId.trim()));
    }
}

