        if (!settings.permissions(sheet).allows("open", roles.of(sheet, input.user()))) {
            result.set(new BulkOpenResponse(0, input.claimIds().size()));
            return;
        }
        for (Person person : people.list(sheet)) {
            List<Claim> theirs = claims.listForPerson(sheet, person.id()).stream()
                    .filter(c -> input.claimIds().contains(c.id())).toList();
            for (Claim claim : theirs) {
                if (claim.status().canBecome(ClaimStatus.OPEN) && periods.closedOn(sheet, claim.dueBy()) == null
                        && PeriodCap.reached(claim, periods, claims) == null
                        && ClaimStatusChange.noteRequired(claim, claims, people, rates, settings, sheets) == null
                        && !flagged(claim, input.user(), roles, flags)) {
                    Rollup before = rollups.take(sheet);
                    boolean review = ClaimStatusChange.reviewRequired(claim, claims, people, rates, settings, sheets);
                    String number = review ? null : claims.nextNumber(sheet, claim.dueBy());
                    claims.changeStatus(claim, review ? ClaimStatus.REVIEW : ClaimStatus.OPEN, number,
                            claim.settledDue(), input.user());
                    log.record(claim, input.user());
                    audit.record((review ? "CLAIM_REVIEW" : "CLAIM_OPENED") + " sheet=" + sheet + " by=" + input.user()
                            + " person=" + person.name() + " amount=" + claim.amount().toPlainString()
                            + " date=" + claim.date() + (review ? "" : " number=" + number));
                    rollups.record(sheet, input.user(), before);
                    opened++;
                }
            }
        }
        result.set(new BulkOpenResponse(opened, input.claimIds().size() - opened));
    }

    private static boolean flagged(Claim claim, String user, RoleRepository roles, FlagRepository flags) {
        try {
            RefuseFlaggedOpen.refuse(claim, user, roles, flags);
            return false;
        } catch (ClaimStatusNotAllowedException e) {
            return true;
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the body and refuse it before anything is read: a signed-in user, a known action, and a reason for a
 *  reject (a resettle freezes a SETTLED claim again; a delete makes a DRAFT DELETED, a restore a DELETED one a DRAFT again). A void's reason, chosen from the sheet's list, is kept
 *  (blank: none) and checked once the claim is loaded. */
public class ValidateClaimStatus {
    public void validate(@RequestBody ClaimStatusRequest request, Out<ClaimStatusInput> body)
            throws InvalidClaimException {
        if (request == null || request.user() == null || request.user().isBlank()) {
            throw new InvalidClaimException("Sign in before changing claims.");
        }
        String action = request.action() == null ? "" : request.action().trim();
        ClaimStatus to = switch (action) {
            case "open", "reject", "review" -> ClaimStatus.OPEN;
            case "settle", "approve", "resettle" -> ClaimStatus.SETTLED;
            case "void" -> ClaimStatus.VOID;
            case "delete" -> ClaimStatus.DELETED;
            case "restore" -> ClaimStatus.DRAFT;
            default -> throw new InvalidClaimException("Unknown claim action: " + action + ".");
        };
        String reason = null;
        if (action.equals("reject")) {
            reason = request.reason() == null ? "" : request.reason().trim();
            if (reason.isEmpty()) {
                throw new InvalidClaimException("Give a reason to reject a claim.");
            }
        } else if (action.equals("void") && request.reason() != null && !request.reason().isBlank()) {
            reason = request.reason().trim();
        }
        body.set(new ClaimStatusInput(request.user().trim(), action, to, reason));
    }
}
